INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1199263-che304', 'stk-chemist', 'CHE 304', 'info', '{"desc": "جودة المقرر بشكل عام:\nمهم وممتاز جدا في عملية انتقال المادة\n\nالمواضيع التي يغطيها المقرر:\n1) تعرف انتقال المادة\n2) حساب معامل انتقال المادة أو معامل الإنتشار\n3) Mass trasfer under nonsteady State condition\n4) انتقال المادة في أجسام مختلفه\n\nتكمن صعوبة المادة في Mass trasfer under unsteady State condition حيث يكون عندك معادلات تفاضلية وتكامل\n\nالكتاب المستخدم للمقرر:\nممتاز جدا وبعيد عن التفاصيل اللي مالها داعي\n\nالأسئلة والأمثلة المستخدمة في المقرر:\nالأمثلة قليلة أما التمارين فصراح أبدع المؤلف في كتابتها\n\nمدى فائدته في الناحية التطبيقية:\nمهم جدا في حياتك المهنية بل هو فرع لوحده قد تكون وظيفتك عليه لما تتخرج\n\nهناك كثير من الإشاعات يوم كنا سفرمور ان هذا الكورس من أصعب الكورسات في الهندسة الكيميائية ولكنه بعد الدراسة اتضح لنا ان الكورس عادي ومثل أي كورس ولكن موضوع unsteady State condition يبيك تشتغل عليه شوي ولا الكورس كله قانون وطبق", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/che-304-transport-phenomena-iii/120653/2", "user": "Chemist", "ts": 1363226189000, "tid": 120653, "pn": 2}}', 1363226189000, 1794774613, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1212409-che304', 'stk-user6687', 'CHE 304', 'info', '{"desc": "كورس سهالات بس نزلوه مع دكتور يعرف يشرح\nانك تذاكر وتحل الأسئله سهل\n\nلكن المهم هو الفهم الي بيفيدك بعد التخرج\nاختبارات الماده open book\n\nفيه جزء يشبه الـ fluid mechanics في طبية الأسئله والي اقصد فيها هو الـ differential equations\nأكثر جزء مهم من الماده هو الجزء الأخير بعد ميجر 2\n\nالكتاب جدا متفرع ولكن بيخترون شباتر ومواضيع معينه", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/che-304-transport-phenomena-iii/120653/3", "user": "user6687", "ts": 1366295037000, "tid": 120653, "pn": 3}}', 1366295037000, 1794774613, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1431545-che304', 'stk-_3111', 'CHE 304', 'info', '{"desc": "الغلطة تكلف كثير في هذا الكورس لأن الآفرج عالي، في تشابتر واحد صعب اللي هو تقريبا ثالث تشابتر اما الباقي يعتبر سهل جدا من ناحية الحل، لاحظ الحل وليس الفهم", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/che-304-transport-phenomena-iii/120653/6", "user": "_3111", "ts": 1446155183000, "tid": 120653, "pn": 6}}', 1446155183000, 1794774613, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1437729-che304', 'stk-medoalkebsi', 'CHE 304', 'info', '{"desc": "ترم 151\n\nالكورس هذا تسليكي جدآآآآآ … كورس خفيف . الميتيريل حقه قصير جدآآآ . يعني تحصل الدكتور يجلس يشرح لك شابتر قصير في اسبوعين. اخر اسبوعين في السمستر جا وقد اغلب السكاشن خلصت المتيريل .\n\nالكورس يحتاج منك عشان تجيب قريد كويس , تعرف كيف تستخدم المعادلات الي بالفورميلاشيت. الكونسبت فيها خفيف جدآ .", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/che-304-transport-phenomena-iii/120653/7", "user": "Medoalkebsi", "ts": 1451722057000, "tid": 120653, "pn": 7}}', 1451722057000, 1794774613, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1438022-che304', 'stk-gamofrn', 'CHE 304', 'info', '{"desc": "304 -term 151-مع الدكتور الجهني\n\nجودة المقرر بشكل عام: المقرر مفيد جدا للكمكل انجينيرز… حيث يغطي عدة حالات لأنتقال المادة …\n\nالمواضيع التي يغطيها المقرر :\n\nالدروس تبدأ من تشابتر 22 الى تشابتر 28 … يعني الكورس 6 تشابترات\n\nتشبتر 22 : يتكلم عن انتقال المادة بين سائل وسائل … غاز وغاز …\nوانتقال سائل سائل او غاز غاز في المواد الي فيها نتوءات\n\nتشبتر 23 + 24 : يتكلم عن حساب مولر فلكس … وبهالتشابر\nفي 6 ستيبز تطبق لحل المسائل من الدكتور الجهني …\nوفيها ماث … انتقيرشن بسيط … وافكاره وحدة\n\nتشبتر 25 : يتكلم عن انتقال المادة في حالة unsteady state …\nل very large system و semi-infinite system وثنينهم سهلات\n\nتشبتر 26 : يتكلم عن انتقال المادة من صفيحة صلبه … الى غاز او سائل …\nوهنا تستخدم قواني ريلنولدز…شاورد…الخ … ونفس الكلام … الأفكار والأسئلة ثابته\n\nتشبتر 27 : يتكلم عن انتقال المادة بين غاز الى سائل = absorption\nسائل الى غاز عن طريقتين تعرف ب striping …\nنفس المغزى … لكنهم عكس بعض بالعملية\n\nتشبتر 28 : تكملة لتشبتر 26 … لكن الأختلاف بالجيومتري … حيث بشبتر 26\nكان الأنتقال يكون من صفيحة … لككن به>ا التشبتر يكون من سفير … او بيب … الخ\n\nالكتاب المستخدم للمقرر: الكتاب … جيد …\nالأسئلة والأمثلة المستخدمة في المقرر: جيدة\nمدى فائدته في الناحية التطبيقية: في اسئلة تدخل بحياتنا اليومية … واشوفها مفيدة …\n\nنصيحة : نزل عند الجهني … لأن يعطيك الزبدة من كل درس …\nوالأسئلة الي يحلها تجي بالماياجر اشيا شبيها لها. وشرح كافي ووافي\nمااقول انه ممتاز … لكنه الأفضل من السيئين … حيث يعطي هند اوت …\nتلخص ستبز معينه … وعطانا اوف فوق ال 7 مرات يمكن … ولا يطول بالمحاضرة … نص ساعة غالبا", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/che-304-transport-phenomena-iii/120653/8", "user": "GAMOFRN", "ts": 1451920143000, "tid": 120653, "pn": 8}}', 1451920143000, 1794774613, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1449945-che304', 'stk-k_94', 'CHE 304', 'info', '{"desc": "كورس سهل وجدا خفيف , انا جيت مع مدرس ما يعرف يشرح هذرته واجد , ولكن لو تحل الهوموورك وتفهم طريقته صدقني ما تحتاج مدرس ولا اوفيس هاور\n\nكل الكورس تقريبا تطبيق مباشر ما عدا تشابتر 24 في معادلات تفاضليه وتكامل وخرابيط الباقي سهل\n\nواللي سهله علينا ان الترم هذا كان close book , يعني الفورملا تجيك جاهزه ما تتعب وانت تدور بالكتاب بالميجر\n\nاللي اعابها الترم هذا سوء التنسيق بين المدرسين كل واحد يعطي طلابه كلمه ونتفاجئ بشي مغاير بالاختبار\n\nالفانيل قالوا لنا سؤال من 27 و سؤال من 28 وسؤالين من ميجر 1 و 2 كلا على حدة , تفاجئنا بالاختبار انهم غيروا الفورملا اللي ارسلوها ( ولكنها وافيه )\n\nوحطو سؤالين من 27 وسؤال من 28 وسؤال من ميجر 1 ,\n\nعالعموم انت ركز عالHw وما يصير الا خير ان شاء الله", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/che-304-transport-phenomena-iii/120653/9", "user": "K_94", "ts": 1463870794000, "tid": 120653, "pn": 9}}', 1463870794000, 1794774613, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1457329-che304', 'stk-muntathir', 'CHE 304', 'info', '{"desc": "153\nكورس سهل و خفيف و مشابه ل300 فتأخذهم مع بعض ما راح يكون صعب\n* الكتاب جميل جدا في وضع الأمثلة و التمارين -practical problems-\n* السيلبلس مرفقة", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/che-304-transport-phenomena-iii/120653/10", "user": "muntathir", "ts": 1473435035000, "tid": 120653, "pn": 10}}', 1473435035000, 1794774613, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1467620-che304', 'stk-user9534', 'CHE 304', 'info', '{"desc": "هههههههههههههههههههههههههه هذا أكثر كورس تسليكي بالكيمكال , أغلب الناس مايدرون وش الطبخة\nالكتاب سيء وكنا نذاكر من السلايدات ومن أسئلة الواجب وأغلب الشعب C,C+ وماحنا فاهمين شيء xD\nأفرج الفاينل حقنا كان 55% , أقولك كل الشعب مو فاهم ويسلكون\nمدري وش أقولك بس سلك لذا الكورس , ذاكر السلايدات والواجب وخلاص طز ياشيخ xD", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/che-304-transport-phenomena-iii/120653/11", "user": "user9534", "ts": 1486248117000, "tid": 120653, "pn": 11}}', 1486248117000, 1794774613, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-chemist-che304', 'stk-chemist', 'CHE 304', 'doc', '{"docs": [{"id": "stk-dr-f98537", "n": "Dr. A Al-Juhani", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Term 111 - CHE 304\nالتحضير:\nمافيه تحضير نهائيا\n\nالشرح:\nملك في الشرح يعطيك الزبدة ولا يكثر عليك ويقول لك وش المطلوب وش الغير مطلوب\n\nالكويزات:\nكانت كلها تيك هوم وسهالات\n\nالمياجر والفاينال:\nكومون بس بما انه هو الكوردينيتور كانت المياجر سهله جدا مقارنة بالفصول الماضية والفاينال كان اسهل منها\n\nاضافات:\n1) الدكتور اخلاق وحبيب ومتعاون\n2) الله يسهل عليه مثل ماسهل علينا لدرجة ان CHE 304 كانت في الفصل الماضي اسهل من CHE 300 & 303 بدون مبالغة\n\nالقريد النهائي:\nانا اعطيه +A في 304 وذا شفت اسمه نزل معاه دون تردد لانه متمكن منها\nهذا الكلام كله في 304 يمكن المواد الثانيه مايكون شرحه مثل 304", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p979386-che304", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/a-al-juhani/98537/17", "user": "Chemist", "ts": 1328313857000, "tid": 98537, "pn": 17}}]}', 1328313857000, 1794774613, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-a-alajmi-che304', 'stk-a-alajmi', 'CHE 304', 'doc', '{"docs": [{"id": "stk-dr-f98538", "n": "Dr. Mamdoh Al-Harthi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Che 304 -171\n\nالتحضير :\nبالأسماء وغالبا في بداية الكلاس , مو دائما يحضر على حسب المزاج\n\nطريقة الشرح :\nأحيانا تحسه انسان فاهم وأحيانا تحس أنه ما يدري أصلا وش الي في السلايدات - نظامه يفتح سلايدات ويقرأ منها\nالكويزات :\n\nيحدد لك عدد معين من الأسئلة ويجيبلك واحد منها غالبا 3 -4\nالمياجر:\nكومون\nالفاينلات :\nكومون\nالقريد النهائي:\nC\nالصوت:\n\nعادي ونبره وحدة ما تتغير طول الكلاس\nإضافات :\n\nالدكتور أخلاقه عالية وابتسامته ما تفارقه ولكن فيه عدة نقاط وملاحظات :\n\n1- جاب الميجر الثاني عليه 20 بوينت والميجر أصلا 20% من الكورس , يعني كل درجة ب 1% !!!!!\n2- جيته أكثر من مرة المكتب وما حصلته\n3- بداية الترم كان شرحه ممتاز ولكن مع مرور الأيام بدى ينحدر المستوى وصرنا ما نحضر الا عشان التحضير !", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1484958-che304", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mamdoh-al-harthi/98538/19", "user": "A-Alajmi", "ts": 1514122015000, "tid": 98538, "pn": 19}}]}', 1514122015000, 1794774613, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user7399-che304', 'stk-user7399', 'CHE 304', 'doc', '{"docs": [{"id": "stk-dr-f98539", "n": "Dr. Reyad Shawabkeh", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "che304\nترم 123\nالتحضير\nتحضير يومي وما يحب التاخير ابدا ولكن يثق في الطلاب ومتفهم لوضعهم يعني لو غبت رح عنده وما راح يقصر معك ولو كان عندك رحلة بلغه وراح ياذن لك\nطريقة الشرح\nجداا شريح ويربط الماده بالواقع والنوت اللي يكتبها في الكلاس كافية للماده\nالهوموركات\nيعطي تقربيا هومورك كل اسبوع ونص طبعا الهوموركات سهلة وكان يجيب من اسئلة الكتاب اغلب الاوقات وكان يقول اللي ما عنده المانوال يجيء ياخذه من عندي\nالكوزات جدا سهلة ومن الهوموركات\nالمياجر\nطبعا كان هو الدكتور الوحيد اللي يدرس الماده في الصيف وكان يجيب الاسئلة من الهوموركات وكان يتجنب الاسئلة اللي فيها صعوبة\nالقريد A+", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1286512-che304", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/reyad-shawabkeh/98539/10", "user": "user7399", "ts": 1384294935000, "tid": 98539, "pn": 10}}]}', 1384294935000, 1794774613, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-abo_fauzi-che304', 'stk-abo_fauzi', 'CHE 304', 'doc', '{"docs": [{"id": "stk-dr-f98544", "n": "Dr. Oki Muraza", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "CHE 304 - Term 161\n\nالتحضير : كل كلاس يحضر على الكمبيوتر والله ما تدري هو من جد يحضر ولا بس يقرأ الأسماء 😆\n\nطريقة الشرح : أي شرح ؟؟ الشرح في وادي والدكتور في وادي ثاني والله لو انه يشرح لجدار كان نفس الشيئ ما تفرق ! :no_entry_sign: طول الكلاس وهو يقعد يطالع في الأسماء ويختار ضحية ويعطيه سؤال وفي الغالب محد يجاوب لأنو هذي هي طريقة شرحة بالضبط كل الكلاسات !!!!! وعاد ما يحتاج أقول اللي على جواله واللي يكلم خويه واللي نص الحصة وهو طالع أصلاً 😆\n\nالكويزات : أختبرنا 3 كويزات طول الترم وقالنا حياخذ درجة أحسن كويز\n\nالمياجر والفاينل : كومن مع دكتور محمد حسين\n\nالقريد النهائي: D بسبب تصحيحه ولا المفروض F\n\nالصوت: واضح\n\nإضافات : الدكتور ذا ما فيه إلا ميزة وحدة وهي ميزة بطلة صراحة … تصحيحه خوراااااااااااااافي للاختبارات … لو جوابك في الشرق والحل الصح في الغرب حتاخذ 8/10 كيف لا تسأل 😀 انت أهم شيء لا تسيب أي سؤال فاضي أصرفله أي حاجة وصدقني حتاخذ عليها درجة كويسة كمان وفي النهاية باين انه يدف في القريدات يعني مرة عادي تاخذ B وانت مو فاهم ولا شيء في الكورس ! 👋", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1467105-che304", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/oki-muraza/98544/12", "user": "Abo_Fauzi", "ts": 1485539828000, "tid": 98544, "pn": 12}}]}', 1485539828000, 1794774613, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-guest-che304', 'stk-guest', 'CHE 304', 'doc', '{"docs": [{"id": "stk-dr-f98546", "n": "Dr. Halim Redhwi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Che 304\n\nشرحه جيد جدا و ممتع\nو يربط لك الشرح بتطبيقات عملية في الشركات\nو يستطرد في الشرح لكن يفيدك في تكوين خلفية\nعن التخصص ممتازة جدا\n\nهوموركات على كل شابتر\n\nكويزات لا يوجد\n\nمياجر متوووسطة تميل للسهولة\n\nتقييمي : A\n\nآنصح فيه و بقوووووة", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p742359-che304", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/halim-redhwi/98546/2", "user": "Guest", "ts": 1292143244000, "tid": 98546, "pn": 2}}]}', 1292143244000, 1794774613, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-k_94-che304', 'stk-k_94', 'CHE 304', 'doc', '{"docs": [{"id": "stk-dr-f98546", "n": "Dr. Halim Redhwi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "CHE 304 - TERM 152\n\nالتحضير : بداية الكلاس\n\nطريقة الشرح : نوتات من عهد الطفرة يكتبها بالسبورة ويقعد يهذر فيها , وفوق كذا ما يحل امثلة , واسئلة الهوموورك ينقل السلوشن عالسبورة , جدا جدا سيئ بالشرح انا اعتمدت على مذاكرة الهوموورك\nالكويزات : عليها 10% ولكنه ما يعطي كوزات , يقول باعطيها من راسي للي اشوفه يشارك !!! , ونهاية السمستر ما يعلمك كم اخذت فيها يعني 10% ما ندري وش مصيرها\nالمياجر: كانت سهله جدا كل مياجري فوق الافرج بالرغم اني مو فاهم الا الهوموورك كيف احله ( بالمناسبة السمستر هذا كل دكتور يصحح لطلابه ويحط قريدات طلابه يعني افرج سكشن )\nالفاينلات : كان اصعب بكثير من المياجر وجا خلاف اللي قالوا حيث انهم قالوا المتيريال القديم 50% والجديد 50% , اللي صار الجديد 75% والقديم 25%\n\n-----\nاضافة : الدكتور بداية الترم قال لنا وش رايكم بدل ما نخلي المحاضره UTR نخليها UT وتسير مدتها ساعه وربع والخميس off ؟\n\nطبعا احنا شفناه كويس ووافقنا وخلانا نوقع اقرار بموافقتنا !!\n\nطلع ان الدكتور عنده سفرات ومؤتمرات خلال الاسبوع ( هو الCEO حق وادي الظهران ) فسار اذا غاب الثلاثاء او الاحد يجبرنا نجي الخميس !!\n\nوالمياجر رفض يعطي off يقول انا اعطيكم السمستر كله الخميس off 🤔\n\nالدكتور يشرح عشر دقايق ربع ساعه وبعدها يقعد يسولف عن تجاربه في المصانع والسفرات باقي المحاضره ( افرج ميجر 1 عنده 70% والسكشن الثاني 79%\n\nالميجر الثاني افرجنا 78% وافرجهم 91 % !! )\n\nالحمدلله انه يدرس سكشن واحد كل سنة لا يتورطوا معه الطلاب\n\nبالنسبة لتوزيع القريدات ما ادري عنه للحين ما نزلها ولكن مستحيل باقي اشوف اسمه وانزل معه كورس\n\nافضل شي في الدكتور تصحيحه خرافي جدا جدا ما قد شفت تصحيح افضل من همن يوم دخلت الجامعه ( المياجر والفاينل كلهم رتن )", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1449990-che304", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/halim-redhwi/98546/11", "user": "K_94", "ts": 1463911295000, "tid": 98546, "pn": 11}}]}', 1463911295000, 1794774613, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user6661-che304', 'stk-user6661', 'CHE 304', 'doc', '{"docs": [{"id": "stk-dr-f98551", "n": "Dr. Nadhir Al-Baghli", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Che 304 - الترم 112\n\nالدكتور شريح ومتمكن وما عليه كلام ونوته ممتاز جدا ❤️ …\n\nبس عيبه ياخذ وقت طويل جدا في اشتقاق القانون !!!\n\nفيه طلاب يحبون هالحركة بس عني شخصيا اشوف انه يضيع وقت اطول من اللازم في اشتقاق قوانين جاهزة وموجودة في الكتاب !\n\nاحيان كثييييرة ما يحضر بس ما يحب التأخير (أبداً) !!\n\nكويزاته كانت (كوبي بيست) من الهوموورك …\n\nاعطيه b", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1048310-che304", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/nadhir-al-baghli/98551/14", "user": "user6661", "ts": 1338418247000, "tid": 98551, "pn": 14}}]}', 1338418247000, 1794774613, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-bf7-che304', 'stk-bf7', 'CHE 304', 'doc', '{"docs": [{"id": "stk-dr-f98551", "n": "Dr. Nadhir Al-Baghli", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Dr. Nadhir A. Al-Baghli\n\nبنود التقييم :\nترم ٢٠٢ اونلاين مادة CHE304\nالتحضير : بالاسماء اول دقيقة ونص ويسأال مرات واللي يرد يغيبه\nطريقة الشرح : يشرح على تابلت شرحه متوسط\nالكويزات : متوسطة\nالمياجر: كوردنيتد لكن سؤاله متوسط\nالفاينلات : كوردنيتد وسؤاله متوسط الى صعب شوي\nالقريد النهائي: B\nالصوت: واضح نوعاً ما\nإضافات : دكتور سئ بالتعامل وغدار بالدرجات لازم تكون حريص ومتابع معه درجاتك اول ب اول ويسلبك حقك\nنزل الدرجات في الترانسكربت على طول بدون مايشيكون الطلاب درجاتهم وفيه اخطاء كثير بالرصد عنده\nويكذب بتوزيع القريدات بعد ما تعدل درجاتك المرصودة بالخطأ عشان مايتعب نفسه ويغيرها بالترانسكربت ، وفكرت الترانسكربت عشان يصعب تعديل الدرجات ويحاول مايغير اي قريد عشان مايتعب، يكذب بالقريدات يقول ان التوزيع 77 B وفيه طلاب من 73 B ويقول ال B+ من 86 والله لو ان الافرج مليون ماصارت كذا مع ان فيه طلاب يدرسون عنده وعند غيره 86 A المهم انه كذاب بالدرجات وجحود ومن الاترام الللي قبلها الطلاب يشتكون من ذا الشي", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1529988-che304", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/nadhir-al-baghli/98551/22", "user": "BF7", "ts": 1621339549000, "tid": 98551, "pn": 22}}]}', 1621339549000, 1794774613, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-mjehad-che304', 'stk-mjehad', 'CHE 304', 'doc', '{"docs": [{"id": "stk-dr-f115327", "n": "Dr. Mohammad Hossain", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "CHE 304- Term 131\nالتحضير : يوميا ورقة تمر عالطلاب ومتساهل جدا في التحضير تقدر تحضر طلاب الكلاس كلهم\n\nطريقة الشرح : ملخبطة نوعا ما يعني الدكتور فاهم بس مو مرتب السبورة في كل جهة يتكلم عن شي\nانا اشوف اكبر عيب في شرحه انه موووووووو مرتب مررررررررررررة يعني لو تركز معه وترتب نوته المخربط اللي عالسبورة يمكن تمشي كويس\n\nالكويزات : سهلة جدا الكويز وتسليم الهوم ورك يكون في نفس اليوم والكويز يكون سؤال او سؤالين من الهوم ورك احسن مافيه ما يطلع برة الهوم ورك في الكويزز نهائيا يجيبه بالارقام\nالمياجر: متوسطة مائلة للسهولة\nالفاينلات : متوسطة مائلة للصعوبة\nالقريد النهائي: B\nالصوت: عالي ومسموع لكن الاكسنت الهندي مو واضح شوي يعني في أول أسبوعين في السمسمتر راح تعاني بعدين خلاص تفهم عليه\n\nإضافات : الدكتور طيب ومتسااعد ولكنه شديد في التصحيح حبتين\nالكلاس وورك مضمووون عنده لان زي ماذكرت الهوم ورك والكويز نفس الشي يعني الكلاس وورك في جيبك ان شاْ الله وفي النهاية اذا حس انك مهتم في المادة صدقني بتحصل قريد ما تتوقعه نهائيا", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1393526-che304", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mohammad-hossain/115327/20", "user": "mjehad", "ts": 1409118231000, "tid": 115327, "pn": 20}}]}', 1409118231000, 1794774613, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-muntathir-che304', 'stk-muntathir', 'CHE 304', 'doc', '{"docs": [{"id": "stk-dr-f115330", "n": "Dr. Shaikh Abdurrazzak", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "153\nche 304\nالسيلبلس مرفقة\nالشباب ما قصروا :raised_hand: لكن عندي بعض النقاط:\n* تصحيحه كويس 👍\n* الكوزات أغلبها من الهومورك\n* الميجر الأول سهل فحب ينزل الأفرج فكان الميجر الثاني ضيق في الوقت بالنسبة للأسئلة فنزله و الفاينل سؤالين لشبترين في ساعة -ضيق كذلك- لكن بشكل عام أسئلته مش صعبه تقدر حتى تجيب كامل 🚬\n* جاب في الفاينل تحويل من in & ft إلى m و الكتاب ما فيه تحويل فاكتشفت كيف من الحاسبة في الفاينل فضاع الوقت 🤪\n*إهو يرسل حل الهومورك لكنه حل للكتاب القديم و ليس شرطا أن يكون صحيحا أو كاملا فرح له الساعات المكتبية و سأله فيمكن يجيبها في الميجر كما حصل", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1457326-che304", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/shaikh-abdurrazzak/115330/13", "user": "muntathir", "ts": 1473433672000, "tid": 115330, "pn": 13}}]}', 1473433672000, 1794774613, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-shmshm-che304', 'stk-shmshm', 'CHE 304', 'doc', '{"docs": [{"id": "stk-dr-f153220", "n": "Dr. Isam Al-Jundi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Che304-T211\n\nالتحضير : في الغالب ما يحضر حضر حول خمس او ست مرات طول السمستر وجا في احد الايام شاف في الكلاس بس عشر طلاب قال بوب كويز واقنعوه انه يكنسل جه ويصير بونص على كويز قديم لان ما فيه احد فاهم\nطريقة الشرح : سلايدات ويقراها واذا علق في شيء قال تاخذونه في الهيت ترانسفير ان شاء الله\nالكويزات : اختبرنا كويزين او ثلاثه وكانت اسئلة من الكتاب يجيبها في ورقة خارجيه ويعطيك ورقة تحل عليها\nالمياجر: كومن وكان تصحيحه كويس جدا ما كان يخصم على اي شيء\nالفاينلات : كومن ما اعطانا درجات الفاينل\nالقريد النهائي: B\nالصوت: اخر صف ما تسمعه زين\nإضافات : الدكتور بعض الاحيان يقعد يحشر الطلاب اللي جالسين اخر صف لان محد منتبه معه لان الكل ضايع مع المادة ذي التحشير ما يسجل عليك شيء او ينقصك درجات بس يبيك تركز معه. فيه تقريبا اربع او خمس هوموركات و بروجيكت الهوموركان من اسئلة كتاب. البروجكت بعد كان من اسئلة الكتاب بس كان حله طويل شوي. اذا فيه دكتور ثاني مع الجندي شف وش وضعه واتوقع انه بيكون احسن رح له", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1535042-che304", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/isam-al-jundi/153220/18", "user": "Shmshm", "ts": 1660654471000, "tid": 153220, "pn": 18}}]}', 1660654471000, 1794774613, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-silence-che304', 'stk-silence', 'CHE 304', 'doc', '{"docs": [{"id": "stk-dr-f185295", "n": "Dr. Sagheer Ahmed Sagheer Onaizi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "CHE 304 - T241\n\nبسم الله الرحمن الرحيم،\n\nالتحضير:\nدايم يحضر، على ورقة تمشي عليكم، بالله لاتفكر تحضر خويك لان عز الله اذا انتبه الدكتور ماراح يسوي خير في كامل سكاشنه، ف ارجوك لاتنكب الدفعة معك\n\nالشرح:\nشرح الدكتور فوق الممتاز، يشرح من سلايداته و يشرح و يحل كل شي بالتفصيل، يكتب في السبورة كثير، الدكتور يذكر نقاط مهمة و يمثل لك كيف ممكن يلعب في الاسئلة فيها\n\nالكويزات:\nمتوسطة و اغلبها من الواجب\n\nالمياجر:\nمتوسطة، الدكتور كان يجيب ٣ اسئلة، اثنين واضحين و واحد فيه فكرة شوي، الافرج كان ٧٠٪؜ للاول و ٨١٪؜ للثاني\n\nالفاينل:\nالفاينل كان كومبرهنسف صعب شوي\n\nالتصحيح:\nتصحيح الدكتور ممتاز و يدف و يعطيك فوق حقك\n\nالصوت:\nواضح و لغته ممتازة\n\nالقريد النهائي:\nA+\n\nاضافات:\nالدكتور قمة الاخلاق، جدا حبيب و تعامله جدا طيب مع الطلاب، الدكتور يسمع للطلاب و متساهل في التأجيل و اصلا يعطيكم خبر عن المواعيد الي تبون قبلها بفترة كافية،،، نصيحة، الدكتور جدا متعاون و حليل في كل شي، لكن الي على الطلاب هو ان يكونون في حسن الظن عند الدكتور بدون لف و دوران، الدكتور من بداية الترم يوضح كل شي لكم، طبعا من الاشياء الي شدد عليها هي ان لحد يحضر خويه،،، في ترمنا، الفاينل كان كومبرهنسف حسب السيلبس، بعض الطلاب تكلموا معه يخفف الفاينل وافق على طول و كان ناوي يحذف اسوأ كويز و اسوأ واجب و يعطينا كم غياب مجاني، في نهاية الترم قفط اكثر من مرة طلاب يحضرون اخوياهم و الجنون الاكبر ان في منتصف الترم واحد زرف ورقة التحضير كلها 0__0 لكن الدكتور ماحاسب احد على هذي رغم انه ماعجبه الامر ابدا، على كل حال الدكتور بسبب الي حضروا اخوياهم فصل على كامل سكاشنه و جاب فاينل كومبرهنسف صعب + ماحذف ولا كويز و ولا واجب و كل غياب خصم نص درجة عليه حتى لو غياب واحد بس، مع ان الدكتور قال لو الطلاب الي سببوا الامر زاروه بالمكتب و اعتذروا راح يعيد كل شي مثل ماكان بدون مايحاسبهم او يأثر عليهم لكن الحمدلله على كل حال، الدكتور انصح فيه بقوة و لو اشوفه في اي كورس ثاني راح انزل عنده", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1539695-che304", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/sagheer-ahmed-sagheer-onaizi/185295/2", "user": "Silence", "ts": 1748404658247, "tid": 185295, "pn": 2}}]}', 1748404658247, 1794774613, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
